346	package net.officefloor.hq.app.claim;
347	
348	import java.sql.Date;
349	import java.sql.PreparedStatement;
350	import java.sql.Statement;
351	import java.util.List;
352	import org.springframework.jdbc.core.JdbcTemplate;
353	import org.springframework.jdbc.core.RowMapper;
354	import org.springframework.jdbc.support.GeneratedKeyHolder;
355	import org.springframework.stereotype.Repository;
356	
357	/** The claims store, kept per sheet. */
358	@Repository
359	public class ClaimRepository {
360	
361	    private static final String COLUMNS = "id, sheet_id, person_id, amount, claim_date, note, status, claim_number, settled_due, opened_by, stated, stated_due, corrects,"
362	            + " (SELECT c.claim_date FROM claim c WHERE c.sheet_id = claim.sheet_id AND c.person_id = claim.person_id"
363	            + " AND c.claim_number = claim.corrects) AS corrected_date";
364	
365	    private static final RowMapper<Claim> ROW = (rs, n) -> {
366	        Claim claim = new Claim(rs.getLong("id"),
367	            rs.getString("sheet_id"), rs.getLong("person_id"), rs.getBigDecimal("amount"),
368	            rs.getDate("claim_date").toLocalDate(), rs.getString("note"),
369	            ClaimStatus.valueOf(rs.getString("status")),
370	            rs.getString("claim_number"), rs.getBigDecimal("settled_due"),
371	            rs.getString("opened_by"));
372	        claim.bind(rs.getBoolean("stated"), rs.getBigDecimal("stated_due"));
373	        claim.setCorrects(rs.getString("corrects"));
374	        java.sql.Date corrected = rs.getDate("corrected_date");
375	        claim.setCorrectedDate(corrected == null ? null : corrected.toLocalDate());
376	        return claim;
377	    };
378	
379	    private final JdbcTemplate jdbc;
380	
381	    public ClaimRepository(JdbcTemplate jdbc) {
382	        this.jdbc = jdbc;
383	    }
384	
385	    /** The sheet's claims, newest first. */
386	    public List<Claim> findAll(String sheetId) {
387	        return jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? ORDER BY id DESC",
388	                ROW, sheetId);
389	    }
390	
391	    /** The person's claims on the sheet, newest first. */
392	    public List<Claim> findByPerson(String sheetId, long personId) {
393	        return jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? AND person_id = ? ORDER BY id DESC",
394	                ROW, sheetId, personId);
395	    }
396	
397	    /** The claim with this id on the sheet, or null when there is none. */
398	    public Claim find(String sheetId, long id) {
399	        List<Claim> found = jdbc.query(
400	                "SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? AND id = ?", ROW, sheetId, id);
401	        return found.isEmpty() ? null : found.get(0);
402	    }
403	
404	    /**
405	     * Mark the claim OPEN in the store when it is still DRAFT there, holding its row until the
406	     * request commits so two opens of the same claim cannot both go through; false when another
407	     * request changed it first.
408	     */
409	    public boolean markOpened(Claim claim) {
410	        return jdbc.update("UPDATE claim SET status = 'OPEN' WHERE id = ? AND sheet_id = ? AND status = 'DRAFT'",
411	                claim.getId(), claim.getSheetId()) == 1;
412	    }
413	
414	    /**
415	     * The sheet's next claim number, taken in one statement so two claims opened at the same
416	     * moment never share a number; it is never given out again.
417	     */
418	    public int nextNumber(String sheetId) {
419	        return jdbc.queryForObject("SELECT last_claim_number FROM FINAL TABLE"
420	                + " (UPDATE sheet SET last_claim_number = last_claim_number + 1 WHERE id = ?)",
421	                Integer.class, sheetId);
422	    }
423	
424	    /**
425	     * The next number in one period's sequence on the sheet ({@code sequence} '' for claims in no
426	     * period), counting from 1; taken in one statement so two claims opened at the same moment
427	     * never share a number, and never given out again.
428	     */
429	    public int nextNumberIn(String sheetId, String sequence) {
430	        jdbc.update("MERGE INTO period_number p USING (VALUES (CAST(? AS VARCHAR(200)), CAST(? AS VARCHAR(200)))) v (sheet_id, seq_name)"
431	                + " ON p.sheet_id = v.sheet_id AND p.seq_name = v.seq_name"
432	                + " WHEN NOT MATCHED THEN INSERT (sheet_id, seq_name, last_number) VALUES (v.sheet_id, v.seq_name, 0)",
433	                sheetId, sequence);
434	        return jdbc.queryForObject("SELECT last_number FROM FINAL TABLE"
435	                + " (UPDATE period_number SET last_number = last_number + 1 WHERE sheet_id = ? AND seq_name = ?)",
436	                Integer.class, sheetId, sequence);
437	    }
438	
439	    /** Insert a new claim (assigning its id) or update an existing one. */
440	    public void save(Claim claim) {
441	        if (claim.getId() != null) {
442	            jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ?, status = ?, claim_number = ?, settled_due = ?, opened_by = ?, stated = ?, stated_due = ?, corrects = ? WHERE id = ? AND sheet_id = ?",
443	                    claim.getAmount(), Date.valueOf(claim.getDate()), claim.getNote(),
444	                    claim.getStatus().name(), claim.getNumber(), claim.getSettledDue(), claim.getOpenedBy(),
445	                    claim.isStated(), claim.getStatedDue(), claim.getCorrects(), claim.getId(),
446	                    claim.getSheetId());
447	            return;
448	        }
449	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
450	        jdbc.update(con -> {
451	            PreparedStatement ps = con.prepareStatement(
452	                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, status, corrects) VALUES (?, ?, ?, ?, ?, ?, ?)",
453	                    Statement.RETURN_GENERATED_KEYS);
454	            ps.setString(1, claim.getSheetId());
455	            ps.setLong(2, claim.getPersonId());
456	            ps.setBigDecimal(3, claim.getAmount());
457	            ps.setDate(4, Date.valueOf(claim.getDate()));
458	            ps.setString(5, claim.getNote());
459	            ps.setString(6, claim.getStatus().name());
460	            ps.setString(7, claim.getCorrects());
461	            return ps;
462	        }, keys);
463	        claim.setId(keys.getKey().longValue());
464	    }
465	}
