467	package net.officefloor.hq.app.claim;
468	
469	import java.math.BigDecimal;
470	import java.math.RoundingMode;
471	import java.time.LocalDate;
472	import java.time.temporal.ChronoUnit;
473	import java.util.List;
474	import net.officefloor.hq.app.rate.Rate;
475	import net.officefloor.hq.app.setting.Settings;
476	
477	/**
478	 * A claim's due figure, as the screen shows it: the due fixed when it was settled, else the figure
479	 * its person's last statement bound it to (never while it is PENDING), else its live due: its amount times its grade's rate in
480	 * force on its date, divided by 100 and rounded to two decimals, raised to the sheet's floor when
481	 * below it (a correction, a negative amount, has no floor and no late charge). Null for n/a (no
482	 * floor applies to n/a). Every rounding of a claim's live figures is by the sheet's policy date
483	 * ({@link Settings#rounding}): half up when the claim is dated before it, half to even on or after;
484	 * a correction rounds by the date of the claim it corrects.
485	 */
486	public final class ClaimFigure {
487	    private ClaimFigure() {}
488	
489	    public static BigDecimal of(Claim claim, List<Rate> rates, String grade, Settings settings, LocalDate today) {
490	        if (claim.getSettledDue() != null) return claim.getSettledDue();
491	        if (claim.isBound()) return claim.getStatedDue();
492	        return live(claim, rates, grade, settings, today);
493	    }
494	
495	    /** The claim's live due at its grade's rate on its date; a correction has no floor. */
496	    public static BigDecimal live(Claim claim, List<Rate> rates, String grade, Settings settings, LocalDate today) {
497	        RoundingMode mode = rounding(claim, settings, today);
498	        return Rate.inForce(rates, grade, claim.getDate())
499	                .map((pct) -> times(claim.getAmount(), pct, mode))
500	                .map((due) -> claim.isCorrection() ? due : due.max(settings.floor()))
501	                .orElse(null);
502	    }
503	
504	    /** How the claim's live figures round, by the date it rounds by and the sheet's policy date. */
505	    public static RoundingMode rounding(Claim claim, Settings settings, LocalDate today) {
506	        return settings.rounding(claim.getRoundDate(), today);
507	    }
508	
509	    /**
510	     * The claim's due with its late charge on top: its figure ({@link #of}) plus the late charge
511	     * an OPEN or PENDING claim gains while overdue on {@code today}. Null for n/a.
512	     */
513	    public static BigDecimal withLate(Claim claim, List<Rate> rates, String grade, Settings settings,
514	            LocalDate today) {
515	        BigDecimal figure = of(claim, rates, grade, settings, today);
516	        return figure == null ? null : figure.add(late(claim, figure, settings, today));
517	    }
518	
519	    /**
520	     * The late charge on a figure: for an OPEN or PENDING claim past its due-by (its date plus the sheet's
521	     * terms) on {@code today}, the sheet's late percent of the figure for every full 30 days it is
522	     * overdue, rounded to two decimals as the claim rounds; else 0.00. Never bound by a statement:
523	     * it follows the sheet's today until the claim is settled.
524	     */
525	    public static BigDecimal late(Claim claim, BigDecimal figure, Settings settings, LocalDate today) {
526	        BigDecimal none = BigDecimal.ZERO.setScale(2);
527	        if (!claim.isOpen() || figure == null || claim.isCorrection()) return none;
528	        long overdue = ChronoUnit.DAYS.between(claim.getDate().plusDays(settings.terms()), today);
529	        long periods = overdue > 0 ? overdue / 30 : 0;
530	        if (periods == 0) return none;
531	        return figure.multiply(settings.latePct()).multiply(BigDecimal.valueOf(periods))
532	                .divide(BigDecimal.valueOf(100), 2, rounding(claim, settings, today));
533	    }
534	
535	    /** The amount times the percent, divided by 100 and rounded to two decimals. */
536	    private static BigDecimal times(BigDecimal amount, BigDecimal pct, RoundingMode mode) {
537	        return amount.multiply(pct).divide(BigDecimal.valueOf(100), 2, mode);
538	    }
539	}
