556	/**
557	 * Settles the claim and fixes its due: its amount times the rate of its person's grade in force on its date, in force on the
558	 * claim's date, divided by 100 and rounded to two decimals as the claim rounds (by the sheet's policy date), at least the sheet's floor. With no such rate the due is
559	 * not fixed. A claim a statement bound is settled at its bound figure. The late charge it has gained
560	 * by the sheet's today is frozen in on top. The user who opened the claim may not settle it.
561	 * When a clerk (any user not made a steward) settles a claim whose due is above the sheet's clerk
562	 * limit, it goes to PENDING instead, its due left live until a steward approves or rejects it; a
563	 * due of n/a is within any limit.
564	 */
565	public class SettleClaim {
566	    public void apply(@Val Sheet sheet, @Val Claim claim, PersonRepository people, RateRepository rates,
567	            RoleRepository roles, SettingsRepository settingsStore, HttpServletRequest request)
568	            throws InvalidClaimStatusException, SelfSettleException {
569	        Person person = people.find(sheet.id(), claim.getPersonId());
570	        Settings settings = settingsStore.find(sheet.id());
571	        BigDecimal figure = claim.isStated() ? claim.getStatedDue()
572	                : ClaimFigure.live(claim, rates.findAll(sheet.id()), person.gradeOn(claim.getDate()), settings,
573	                        sheet.today());
574	        // The late charge is read while the claim is still OPEN.
575	        BigDecimal late = ClaimFigure.late(claim, figure, settings, sheet.today());
576	        if (!claim.getStatus().canMoveTo(ClaimStatus.SETTLED)) {
577	            throw new InvalidClaimStatusException(claim.getStatus(), ClaimStatus.SETTLED);
578	        }
579	        String user = Audit.user(request);
580	        if (user.equals(claim.getOpenedBy())) throw new SelfSettleException(user);
581	        BigDecimal due = figure == null ? null : figure.add(late);
582	        if (!settings.withinClerkLimit(due) && Role.CLERK.equals(roles.roleOf(sheet.id(), user))) {
583	            claim.moveTo(ClaimStatus.PENDING);
584	            return;
585	        }
586	        claim.moveTo(ClaimStatus.SETTLED);
587	        claim.setSettledDue(due);
588	    }
