614	/**
615	 * A claim's status. It starts as DRAFT, is opened (OPEN) and then settled (SETTLED). A clerk's
616	 * settle above the clerk limit makes it PENDING instead, until a steward approves it (SETTLED) or
617	 * rejects it (back to OPEN). A DRAFT, OPEN or PENDING claim can be voided (VOID). SETTLED and VOID
618	 * are final. Only OPEN, PENDING and SETTLED claims count toward any total.
619	 */
620	public enum ClaimStatus {
621	    DRAFT(null), OPEN("CLAIM_OPENED"), PENDING("CLAIM_PENDING"), SETTLED("CLAIM_SETTLED"), VOID("CLAIM_VOIDED");
622	
623	    private final String auditEvent;
624	
625	    ClaimStatus(String auditEvent) {
626	        this.auditEvent = auditEvent;
627	    }
628	
629	    /** The audit event written when a claim moves into this status. */
630	    public String auditEvent() {
631	        return auditEvent;
632	    }
633	
634	    /** Whether a claim in this status may move to {@code next}. */
635	    public boolean canMoveTo(ClaimStatus next) {
636	        return switch (next) {
637	            case OPEN -> this == DRAFT;
638	            case PENDING -> this == OPEN;
639	            case SETTLED -> this == OPEN;
640	            case VOID -> this == DRAFT || this == OPEN || this == PENDING;
641	            case DRAFT -> false;
642	        };
643	    }
644	}
