898	        List<Claim> sheetClaims = claims.findAll(sheetId);
899	        Map<Long, Figures> figures = new LinkedHashMap<>();
900	        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
901	        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
902	        for (Person person : people.findAll(sheetId)) {
903	            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
904	            BigDecimal due = BigDecimal.ZERO.setScale(2);
