908	                if (!claim.counts(person.isHeld())) continue;
909	                claimed = claimed.add(claim.getAmount());
910	                if (claim.getSettledDue() != null || claim.boundDue() != null) fixed = true;
911	                String grade = person.gradeOn(claim.getDate());
