package net.officefloor.hq.app.claim;

import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/** Records the move, naming the claim with its new person; the line ends with who it moved from and to. */
public class AuditClaimReassigned {
    public void audit(@Val Sheet sheet, @Val Claim claim, @Val Reassignment reassignment, PersonRepository people,
            HttpServletRequest request, Audit audit) {
        audit.record(ClaimAudit.line("CLAIM_REASSIGNED", sheet, Audit.user(request),
                people.find(sheet.id(), claim.getPersonId()), claim)
                + " from=" + reassignment.from() + " to=" + reassignment.to());
    }
}
EOF
cat > 'resources/officefloor/rest/api/sheets/{sheetId}/claims/{claimId}/reassign.POST.yml' <<'EOF'
# Move a DRAFT, OPEN or PENDING claim to another person on the sheet (a steward). A settled or
# voided claim, a clerk, or a person not on the sheet is refused and writes nothing.
validate:
  class: net.officefloor.hq.app.claim.ValidateReassign
  govern: [ transaction ]
  next: loadSheet
loadSheet:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: before
# The sheet's figures before the change, so the rollup lines tell which moved.
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: closed
# A claim dated inside a closed period is a 409 and writes nothing.
closed:
  class: net.officefloor.hq.app.period.CheckClaimPeriod
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ReassignClaim
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaim
  govern: [ transaction ]
  next: audit
# Last before the response: every rule has passed and the change is saved.
audit:
  class: net.officefloor.hq.app.claim.AuditClaimReassigned
  govern: [ transaction ]
  next: rollup
# After the change's own lines: the figures it moved.
rollup:
  class: net.officefloor.hq.app.rollup.AuditRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
EOF
